7	/**
8	 * Normalizes the submitted telephone on create by stripping every non-digit character,
9	 * then requires exactly 10 digits. The 10-digit value is written back onto the request
10	 * in place (the {@code @Val} object is shared with later steps) so downstream steps store
11	 * and return it; anything else is rejected with 400 via {@link InvalidTelephoneException}.
12	 */
13	public class NormalizeOwnerTelephone {
14	
15	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
16	        String telephone = request.getTelephone();
17	        String digits = OwnerTelephones.normalize(telephone);
18	        if (digits.length() != 10) {
19	            throw new InvalidTelephoneException(telephone);
20	        }
21	        request.setTelephone(digits);
22	    }
23	}
