3	/**
4	 * Single source of truth for what a "normalized" owner telephone is: every non-digit
5	 * character stripped. Used by {@link NormalizeOwnerTelephone} when storing and by
6	 * {@link EnsureUniqueOwnerTelephone} when comparing against existing owners, so the rule
7	 * cannot drift between the two steps.
8	 */
9	final class OwnerTelephones {
10	
11	    private OwnerTelephones() {
12	    }
13	
14	    static String normalize(String telephone) {
15	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
16	    }
17	}
