28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date", columnDefinition = "DATE")
57	    private LocalDate registrationDate;
58	
59	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
60	    private Set<Pet> pets;
61	
62	    public String getAddress() {
63	        return this.address;
64	    }
65	
66	    public void setAddress(String address) {
67	        this.address = address;
68	    }
69	
70	    public String getCity() {
71	        return this.city;
72	    }
73	
74	    public void setCity(String city) {
75	        this.city = city;
76	    }
77	
78	    public String getTelephone() {
79	        return this.telephone;
80	    }
81	
82	    public void setTelephone(String telephone) {
83	        this.telephone = telephone;
84	    }
85	
86	    public String getEmail() {
87	        return this.email;
88	    }
89	
90	    public void setEmail(String email) {
91	        this.email = email;
92	    }
93	
94	    public LocalDate getRegistrationDate() {
95	        return this.registrationDate;
96	    }
97	
98	    public void setRegistrationDate(LocalDate registrationDate) {
99	        this.registrationDate = registrationDate;
100	    }
101	
102	    /**
103	     * The owner's name formatted for display as {@code "LastName, FirstName"}.
104	     */
105	    @Transient
106	    public String getDisplayName() {
107	        return this.getLastName() + ", " + this.getFirstName();
108	    }
109	
110	    /**
111	     * The owner's initials: the upper-cased first letters of firstName and
112	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
113	     */
114	    @Transient
115	    public String getInitials() {
116	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
117	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
118	    }
119	
120	    protected Set<Pet> getPetsInternal() {
121	        if (this.pets == null) {
122	            this.pets = new HashSet<>();
123	        }
124	        return this.pets;
125	    }
126	
127	    protected void setPetsInternal(Set<Pet> pets) {
128	        this.pets = pets;
129	    }
130	
131	    public List<Pet> getPets() {
132	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
133	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
134	        return Collections.unmodifiableList(sortedPets);
135	    }
136	
137	    public void setPets(List<Pet> pets) {
138	        this.pets = new HashSet<>(pets);
139	    }
140	
141	    public void addPet(Pet pet) {
142	        getPetsInternal().add(pet);
143	        pet.setOwner(this);
144	    }
145	
146	    /**
147	     * Return the Pet with the given name, or null if none found for this Owner.
148	     *
149	     * @param name to test
150	     * @return true if pet name is already in use
151	     */
152	    public Pet getPet(String name) {
153	        return getPet(name, false);
154	    }
155	
156	    /**
157	     * Return the Pet with the given name, or null if none found for this Owner.
158	     *
159	     * @param name to test
160	     * @return true if pet name is already in use
161	     */
162	    public Pet getPet(String name, boolean ignoreNew) {
163	        name = name.toLowerCase();
164	        for (Pet pet : getPetsInternal()) {
165	            if (!ignoreNew || !pet.isNew()) {
166	                String compName = pet.getName();
167	                compName = compName.toLowerCase();
168	                if (compName.equals(name)) {
169	                    return pet;
170	                }
171	            }
172	        }
173	        return null;
174	    }
175	
176	    public Pet getPet(Integer petId) {
177	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
178	    }
179	
180	    @Override
181	    public String toString() {
182	        return new ToStringCreator(this)
183	
184	            .append("id", this.getId())
185	            .append("new", this.isNew())
186	            .append("lastName", this.getLastName())
187	            .append("firstName", this.getFirstName())
188	            .append("address", this.address)
189	            .append("city", this.city)
190	            .append("telephone", this.telephone)
191	            .append("email", this.email)
192	            .toString();
193	    }
194	}
